# ------------------------------------------------------------ calendar / dates
# working week + holidays are read from the calendar record copied from your P6 export
_days = {int(d): bool(re.search(r"\(0\|\|0\(s\|", body)) for d, body in
         re.findall(r"\(0\|\|(\d)\(\)\((.*?)\)\)\x7f\x7f(?=\s*\(0\|\||\))", CAL_ROW["clndr_data"] + "\x7f\x7f")}
WORKDAYS = {(n - 2) % 7 for n, w in _days.items() if w}      # P6 1=Sun..7=Sat -> python Mon=0..Sun=6
if not WORKDAYS: WORKDAYS = {0, 1, 2, 3, 4, 5}
HOLIDAYS = {(dt.date(1899, 12, 30) + dt.timedelta(days=int(n))) for n in re.findall(r"\(d\|(\d+)\)", CAL_ROW["clndr_data"])}

def is_wd(d):
    d = d.date() if isinstance(d, dt.datetime) else d
    return d.weekday() in WORKDAYS and d not in HOLIDAYS

def wd_count(a, b):
    n, d = 0, a.date()
    while d <= b.date():
        if is_wd(d): n += 1
        d += dt.timedelta(days=1)
    return max(n, 1)

def finish_after(start, ndays):
    d, n = start.date(), 0
    while True:
        if is_wd(d):
            n += 1
            if n >= ndays: return dt.datetime(d.year, d.month, d.day, DAY_END)
        d += dt.timedelta(days=1)

def next_wd(d):
    d = d.date() if isinstance(d, dt.datetime) else d
    while not is_wd(d): d += dt.timedelta(days=1)
    return dt.datetime(d.year, d.month, d.day, DAY_START)

def guid(key): return base64.b64encode(hashlib.md5(key.encode()).digest()).decode().rstrip("=")[:22]

def fmt(v):
    if v is None: return ""
    if isinstance(v, dt.datetime): return v.strftime("%Y-%m-%d %H:%M")
    if isinstance(v, float):
        return str(int(v)) if v == int(v) else f"{v:.4f}".rstrip("0").rstrip(".")
    return str(v).replace("\t", " ").replace("\r", " ").replace("\n", " ")

def table(name, rows):
    f = FIELDS[name]
    out = [f"%T\t{name}", "%F\t" + "\t".join(f)]
    for r in rows:
        extra = set(r) - set(f)
        assert not extra, (name, extra)
        out.append("%R\t" + "\t".join(r.get(k, "") if isinstance(r.get(k, ""), str) and k == "clndr_data" else fmt(r.get(k)) for k in f))
    return "\r\n".join(out)


def at(d, h): return dt.datetime(d.year, d.month, d.day, h) if d else None
def D(s): return dt.datetime.strptime(s[:10], "%Y-%m-%d")
def build(B):
    data = D(B.get("data") or dt.date.today().isoformat())
    pid = re.sub(r"[^A-Za-z0-9_-]", "", B.get("proj", "PRJ"))[:20] or "PRJ"
    acts = B["acts"]; links = B.get("links", [])
    W_ROOT, W_B, W_S, W_I = 14001, 14002, 14003, 14004
    obs = OBS_ROW["obs_id"]
    def w(i, par, seq, short, nm): return dict(wbs_id=i, proj_id=1, obs_id=obs, seq_num=seq, est_wt=1, proj_node_flag="Y" if i == W_ROOT else "N", sum_data_flag="N", status_code="WS_Open", wbs_short_name=short[:20], wbs_name=nm, parent_wbs_id=par, guid=guid(f"w{i}{nm}"))
    bname = str(B.get("bld") or pid)
    wbs = [w(W_ROOT, EPS_PARENT_ID, 100, pid, str(B.get("name") or pid)), w(W_B, W_ROOT, 0, bname, bname), w(W_S, W_B, 1, "SUPPLY", "SUPPLY / PRODUCTION"), w(W_I, W_B, 2, "INSTALL", "INSTALLATION")]
    tasks, cid, tid = [], {}, 56001
    starts, ends = [], []
    for a in acts:
        code = str(a["code"])[:20]; s, f = D(a["start"]), D(a["fin"]); pct = max(0, min(100, float(a.get("pct") or 0)))
        s0 = next_wd(s); f0 = finish_after(s0, max(1, wd_count(s0, f)))
        st = "TK_Complete" if pct >= 99.5 else ("TK_Active" if pct > 0 else "TK_NotStart")
        drtn = wd_count(s0, f0) * HRS_PER_DAY
        t = {k: "" for k in FIELDS["TASK"]}
        t.update(task_id=tid, proj_id=1, wbs_id=W_S if a["ph"] == "SUP" else W_I, clndr_id=CAL_ROW["clndr_id"], rev_fdbk_flag="N", est_wt=1, lock_plan_flag="N", auto_compute_act_flag="N", complete_pct_type="CP_Phys", task_type="TT_Task", duration_type="DT_FixedDUR2", status_code=st, task_code=code, task_name=str(a["name"])[:120], act_work_qty=0, remain_work_qty=0, target_work_qty=0, target_equip_qty=0, act_equip_qty=0, remain_equip_qty=0, target_drtn_hr_cnt=drtn, priority_type="PT_Normal", guid=guid("t" + code), driving_path_flag="N", act_this_per_work_qty=0, act_this_per_equip_qty=0, create_date=data, update_date=data, create_user="NotPrmUser", update_user="NotPrmUser", target_start_date=at(s0, DAY_START), target_end_date=f0, phys_complete_pct=round(pct, 2))
        if st == "TK_Complete":
            t.update(remain_drtn_hr_cnt=0, act_start_date=at(s0, DAY_START), act_end_date=f0, early_start_date=at(s0, DAY_START), early_end_date=f0, late_start_date=at(s0, DAY_START), late_end_date=f0)
        elif st == "TK_Active":
            rem = max(1, int(round(drtn / HRS_PER_DAY * (1 - pct / 100)))); rs = next_wd(max(data, s0)); re_ = finish_after(rs, rem)
            t.update(remain_drtn_hr_cnt=rem * HRS_PER_DAY, act_start_date=at(s0, DAY_START), early_start_date=at(s0, DAY_START), early_end_date=re_, late_start_date=at(s0, DAY_START), late_end_date=re_, restart_date=rs, reend_date=re_, rem_late_start_date=rs, rem_late_end_date=re_)
        else:
            t.update(remain_drtn_hr_cnt=drtn, early_start_date=at(s0, DAY_START), early_end_date=f0, late_start_date=at(s0, DAY_START), late_end_date=f0, restart_date=at(s0, DAY_START), reend_date=f0, rem_late_start_date=at(s0, DAY_START), rem_late_end_date=f0, cstr_type="CS_MSOA", cstr_date=at(s0, DAY_START))
        tasks.append(t); cid[code] = tid; tid += 1; starts.append(s0); ends.append(f0)
    preds = []
    for p, q, ty, lag in links:
        p, q = str(p)[:20], str(q)[:20]
        if p in cid and q in cid and ty in ("FS", "SS", "FF", "SF"):
            preds.append(dict(task_pred_id=90001 + len(preds), task_id=cid[q], pred_task_id=cid[p], proj_id=1, pred_proj_id=1, pred_type="PR_" + ty, lag_hr_cnt=int(lag) * HRS_PER_DAY, comments="", float_path="", aoa_flag="N"))
    proj = dict(PROJECT_DEFAULTS)
    proj.update(proj_id=1, proj_short_name=pid, clndr_id=CAL_ROW["clndr_id"], guid=guid("project" + pid), last_recalc_date=data, plan_start_date=min(starts + [data]), scd_end_date=max(ends + [data]), add_date=data, task_code_prefix="", task_code_prefix_flag="N", wbs_max_sum_level=2, add_by_name="admin", last_tasksum_date="", fcst_start_date="")
    for k in ("last_checksum", "last_fin_dates_id", "last_baseline_update_date", "new_fin_dates_id", "next_data_date", "close_period_flag", "sum_refresh_date", "trsrcsum_loaded", "baselines_to_export", "baseline_names_to_export"): proj[k] = ""
    for k in ("plan_start_date", "scd_end_date", "last_recalc_date", "add_date"): proj[k] = fmt(proj[k])
    parts = ["\t".join(["ERMHDR", P6_VERSION, data.strftime("%Y-%m-%d"), "Project", "admin", "admin", "dbxDatabaseNoName", "Project Management", "USD"]),
             table("CURRTYPE", [USD_ROW]), table("OBS", [OBS_ROW]), table("PROJECT", [proj]), table("CALENDAR", [CAL_ROW]), table("PROJWBS", wbs), table("TASK", tasks)]
    if preds: parts.append(table("TASKPRED", preds))
    return ("\r\n".join(parts) + "\r\n%E\r\n").encode("cp1252", "replace")


# ------------------------------------------------------------ generic Excel program -> XER
# Used by server.py /api/xer/excel. Takes any activity list (ID, name, WBS path, dates and/or durations, % complete,
# predecessors) and writes a complete P6 project: WBS tree, calendar, activities, relationships.
WEEKS = {"company": None, "mon-sat": {0, 1, 2, 3, 4, 5}, "sun-thu": {6, 0, 1, 2, 3}, "mon-fri": {0, 1, 2, 3, 4}, "sat-thu": {5, 6, 0, 1, 2, 3}, "all": {0, 1, 2, 3, 4, 5, 6}}
WEEK_NAMES = {"company": CAL_ROW["clndr_name"], "mon-sat": "6 day week Mon-Sat", "sun-thu": "5 day week Sun-Thu", "mon-fri": "5 day week Mon-Fri", "sat-thu": "6 day week Sat-Thu", "all": "7 day week"}

def _cal_data(work, h0, h1, holidays):
    nl = "\x7f\x7f"; out = ["(0||CalendarData()(", "  (0||DaysOfWeek()("]
    for p6d in range(1, 8):          # P6 1=Sun .. 7=Sat
        if ((p6d - 2) % 7) in work: out += ["    (0||%d()(" % p6d, "      (0||0(s|%02d:00|f|%02d:00)())))" % (h0, h1)]
        else: out.append("    (0||%d()())" % p6d)
    out[-1] += "))"
    out.append("  (0||VIEW(ShowTotal|Y)())")
    hs = sorted(holidays)
    if hs:
        out.append("  (0||Exceptions()(")
        for i, d in enumerate(hs): out.append("    (0||%d(d|%d)())" % (i, (d - dt.date(1899, 12, 30)).days))
        out[-1] += "))))"
    else: out[-1] += ")"
    return nl.join(out)

def _pdate(v):
    s = str(v or "").strip()
    if not s: return None
    m = re.match(r"(\d{4})-(\d{2})-(\d{2})", s)
    if m: return dt.date(int(m[1]), int(m[2]), int(m[3]))
    return None

def build_generic(B):
    acts = B.get("acts") or []
    if not acts: raise ValueError("no activities")
    week = B.get("week") if B.get("week") in WEEKS else "company"
    hpd = max(1, min(24, int(float(B.get("hpd") or HRS_PER_DAY))))
    h0 = max(0, min(23, int(float(B.get("h0") or DAY_START)))); h1 = min(24, h0 + hpd)
    work = WEEKS[week] if WEEKS[week] is not None else set(WORKDAYS)
    hol = set(HOLIDAYS) if week == "company" else set()
    def iswd(d): return d.weekday() in work and d not in hol
    def nwd(d, back=False):
        n = 0
        while not iswd(d) and n < 400: d += dt.timedelta(days=-1 if back else 1); n += 1
        return d
    def addwd(d, n):           # the date n working days after d (n may be negative), d itself a working day
        step = 1 if n >= 0 else -1; n = abs(n)
        while n > 0:
            d += dt.timedelta(days=step)
            if iswd(d): n -= 1
        return d
    def wdays(a, b):           # working days from a to b inclusive
        n, d = 0, a
        while d <= b:
            if iswd(d): n += 1
            d += dt.timedelta(days=1)
        return n
    data = _pdate(B.get("data")) or dt.date.today()
    pstart = _pdate(B.get("pstart"))
    pid = re.sub(r"[^A-Za-z0-9_.-]", "", str(B.get("proj") or "PRJ"))[:20] or "PRJ"
    pname = str(B.get("name") or pid)[:100]
    hold = B.get("hold") if B.get("hold") in ("nopred", "all", "none") else "nopred"
    # ---- activities: clean IDs, durations, links
    A, seen = [], set()
    for i, a in enumerate(acts):
        code = re.sub(r"[\t\r\n]", " ", str(a.get("code") or "")).strip()[:40] or "A%d" % (1000 + 10 * i)
        base, k = code, 2
        while code in seen: code = (base[:36] + "-%d" % k); k += 1
        seen.add(code)
        name = re.sub(r"[\t\r\n]+", " ", str(a.get("name") or code)).strip()[:120]
        typ = str(a.get("type") or "").lower()
        s, f = _pdate(a.get("start")), _pdate(a.get("fin"))
        try: dur = float(a.get("dur")) if str(a.get("dur", "")).strip() != "" else None
        except ValueError: dur = None
        mile = "mile" in typ or (dur == 0) or (dur is None and s and f and s == f and "mile" in name.lower())
        A.append(dict(i=i, code=code, name=name, wbs=[str(x).strip()[:100] for x in (a.get("wbs") or []) if str(x).strip()], s=s, f=f, dur=dur, mile=mile,
                      fmile=mile and ("fin" in typ or (not s and f is not None)), pct=max(0.0, min(100.0, float(a.get("pct") or 0))),
                      as_=_pdate(a.get("as")), af=_pdate(a.get("af")), preds=a.get("preds") or []))
    by = {a["code"]: a for a in A}
    links = []
    for a in A:
        for p in a["preds"]:
            pc = str(p.get("id") or "").strip(); ty = str(p.get("t") or "FS").upper()
            if pc in by and pc != a["code"] and ty in ("FS", "SS", "FF", "SF"):
                try: lag = float(p.get("lag") or 0)
                except ValueError: lag = 0
                links.append((pc, a["code"], ty, lag))
    # ---- dates: keep what the sheet gives, compute the rest (forward pass over the links)
    pre = {}
    for l in links: pre.setdefault(l[1], []).append(l)
    p0 = nwd(pstart or min([x["s"] for x in A if x["s"]] + [x["f"] for x in A if x["f"]] + [data]))
    done, busy = {}, set()
    def sched(a):
        if a["code"] in done: return done[a["code"]]
        if a["code"] in busy: return (p0, p0)               # loop in the logic: break it
        busy.add(a["code"])
        d = 0 if a["mile"] else (max(1, int(round(a["dur"]))) if a["dur"] is not None else None)
        s, f = a["s"], a["f"]
        if s and f and f < s: f = None
        if s and f and d is None: d = 0 if a["mile"] else max(1, wdays(nwd(s), nwd(f, True)))
        if d is None: d = 1
        if not s and f:
            f = nwd(f, True); s = f if d == 0 else addwd(f, -(d - 1))
        elif not s:
            es = p0
            for pc, _, ty, lag in pre.get(a["code"], []):
                ps, pf = sched(by[pc]); lg = int(round(lag))
                if ty == "FS": c = addwd(pf, lg + (0 if (by[pc]["mile"] and not by[pc]["fmile"]) or a["fmile"] else 1))
                elif ty == "SS": c = addwd(ps, lg)
                elif ty == "FF": c = addwd(addwd(pf, lg), -(max(d, 1) - 1))
                else: c = addwd(addwd(ps, lg), -(max(d, 1) - 1))
                if c > es: es = c
            s = nwd(es)
        s = nwd(s)
        if not f: f = s if d == 0 else addwd(s, d - 1)
        f = nwd(f, True)
        if f < s: f = s
        a["d"] = 0 if a["mile"] else wdays(s, f)
        busy.discard(a["code"]); done[a["code"]] = (s, f); return s, f
    for a in A: sched(a)
    # ---- WBS tree
    W_ROOT = 14001; wid = [W_ROOT + 1]; wmap = {}; obs = OBS_ROW["obs_id"]; wseq = {}
    def W(i, par, short, nm, seq): return dict(wbs_id=i, proj_id=1, obs_id=obs, seq_num=seq, est_wt=1, proj_node_flag="Y" if i == W_ROOT else "N", sum_data_flag="N", status_code="WS_Open",
                                               wbs_short_name=short[:20], wbs_name=nm[:100], parent_wbs_id=par, guid=guid("w%s%d%s" % (pid, i, nm)))
    wbs = [W(W_ROOT, EPS_PARENT_ID, pid, pname, 100)]
    def wbs_of(path):
        par, key = W_ROOT, ()
        for nm in path:
            key = key + (nm,)
            if key not in wmap:
                seq = wseq.get(par, 0); wseq[par] = seq + 1
                short = re.sub(r"\s+", "", nm.split(" ")[0])[:20] if len(nm) > 20 else nm
                wmap[key] = wid[0]; wbs.append(W(wid[0], par, short, nm, seq)); wid[0] += 1
            par = wmap[key]
        return par
    # ---- TASK rows
    cal = dict(CAL_ROW); cal.update(clndr_id="990", clndr_name=WEEK_NAMES[week] + " %02d:00-%02d:00" % (h0, h1), day_hr_cnt=hpd, week_hr_cnt=hpd * len(work),
                                     month_hr_cnt=round(hpd * len(work) * 52 / 12), year_hr_cnt=hpd * len(work) * 50, last_chng_date=fmt(dt.datetime.combine(data, dt.time())),
                                     clndr_data=_cal_data(work, h0, h1, hol))
    def AT(d, h): return dt.datetime(d.year, d.month, d.day, min(h, 23), 59 if h >= 24 else 0)
    hasp = {l[1] for l in links}
    tasks, cid, tid = [], {}, 56001
    dd = dt.datetime.combine(data, dt.time())
    starts, ends = [], []
    for a in A:
        s, f = done[a["code"]]; pct = a["pct"]
        if a["af"]: pct = 100.0
        st = "TK_Complete" if pct >= 99.5 else ("TK_Active" if pct > 0 or a["as_"] else "TK_NotStart")
        ttype = ("TT_FinMile" if a["fmile"] else "TT_Mile") if a["mile"] else "TT_Task"
        drtn = 0 if a["mile"] else a["d"] * hpd
        S0, F0 = AT(s, h0), AT(f, h1)
        if a["mile"]: F0 = S0 if not a["fmile"] else AT(f, h1); S0 = S0 if not a["fmile"] else F0
        t = {k: "" for k in FIELDS["TASK"]}
        t.update(task_id=tid, proj_id=1, wbs_id=wbs_of(a["wbs"]), clndr_id=cal["clndr_id"], rev_fdbk_flag="N", est_wt=1, lock_plan_flag="N", auto_compute_act_flag="N", complete_pct_type="CP_Phys",
                 task_type=ttype, duration_type="DT_FixedDUR2", status_code=st, task_code=a["code"], task_name=a["name"], act_work_qty=0, remain_work_qty=0, target_work_qty=0, target_equip_qty=0,
                 act_equip_qty=0, remain_equip_qty=0, target_drtn_hr_cnt=drtn, priority_type="PT_Normal", guid=guid("t%s%s" % (pid, a["code"])), driving_path_flag="N", act_this_per_work_qty=0,
                 act_this_per_equip_qty=0, create_date=dd, update_date=dd, create_user="NotPrmUser", update_user="NotPrmUser", target_start_date=S0, target_end_date=F0, phys_complete_pct=round(pct, 2))
        if st == "TK_Complete":
            as_ = AT(a["as_"], h0) if a["as_"] else S0; af = AT(a["af"], h1) if a["af"] else F0
            if a["mile"]: as_ = "" if a["fmile"] else as_; af = af if a["fmile"] else ""
            t.update(remain_drtn_hr_cnt=0, act_start_date=as_, act_end_date=af, early_start_date=S0, early_end_date=F0, late_start_date=S0, late_end_date=F0)
        elif st == "TK_Active" and not a["mile"]:
            rem = max(1, int(round(a["d"] * (1 - pct / 100)))); rs = nwd(max(data, s)); re_ = addwd(rs, rem - 1)
            as_ = AT(a["as_"], h0) if a["as_"] else S0
            t.update(remain_drtn_hr_cnt=rem * hpd, act_start_date=as_, early_start_date=AT(rs, h0), early_end_date=AT(re_, h1), late_start_date=AT(rs, h0), late_end_date=AT(re_, h1),
                     restart_date=AT(rs, h0), reend_date=AT(re_, h1), rem_late_start_date=AT(rs, h0), rem_late_end_date=AT(re_, h1))
            F0 = AT(re_, h1)
        else:
            t.update(status_code="TK_NotStart", remain_drtn_hr_cnt=drtn, early_start_date=S0, early_end_date=F0, late_start_date=S0, late_end_date=F0, restart_date=S0, reend_date=F0, rem_late_start_date=S0, rem_late_end_date=F0)
            if hold == "all" or (hold == "nopred" and a["code"] not in hasp):
                if a["fmile"]: t.update(cstr_type="CS_MEOA", cstr_date=F0)
                else: t.update(cstr_type="CS_MSOA", cstr_date=S0)
        tasks.append(t); cid[a["code"]] = tid; tid += 1; starts.append(S0); ends.append(F0)
    preds = [dict(task_pred_id=90001 + n, task_id=cid[q], pred_task_id=cid[p], proj_id=1, pred_proj_id=1, pred_type="PR_" + ty, lag_hr_cnt=round(lag * hpd, 2), comments="", float_path="", aoa_flag="N")
             for n, (p, q, ty, lag) in enumerate(links)]
    proj = dict(PROJECT_DEFAULTS)
    proj.update(proj_id=1, proj_short_name=pid, clndr_id=cal["clndr_id"], guid=guid("project" + pid + pname), last_recalc_date=dd, plan_start_date=min(starts + [AT(p0, h0)]), scd_end_date=max(ends),
                add_date=dd, task_code_prefix="", task_code_prefix_flag="N", wbs_max_sum_level=max([len(a["wbs"]) for a in A] + [1]) + 1, add_by_name="admin", last_tasksum_date="", fcst_start_date="")
    for k in ("last_checksum", "last_fin_dates_id", "last_baseline_update_date", "new_fin_dates_id", "next_data_date", "close_period_flag", "sum_refresh_date", "trsrcsum_loaded", "baselines_to_export", "baseline_names_to_export"): proj[k] = ""
    for k in ("plan_start_date", "scd_end_date", "last_recalc_date", "add_date"): proj[k] = fmt(proj[k])
    parts = ["\t".join(["ERMHDR", P6_VERSION, data.strftime("%Y-%m-%d"), "Project", "admin", "admin", "dbxDatabaseNoName", "Project Management", "USD"]),
             table("CURRTYPE", [USD_ROW]), table("OBS", [OBS_ROW]), table("PROJECT", [proj]), table("CALENDAR", [cal]), table("PROJWBS", wbs), table("TASK", tasks)]
    if preds: parts.append(table("TASKPRED", preds))
    xer = ("\r\n".join(parts) + "\r\n%E\r\n").encode("cp1252", "replace")
    summary = {"acts": len(A), "wbs": len(wbs) - 1, "links": len(links), "start": min(starts).strftime("%Y-%m-%d"), "finish": max(ends).strftime("%Y-%m-%d"),
               "computed": sum(1 for a in A if not a["s"] and not a["f"]), "miles": sum(1 for a in A if a["mile"])}
    return xer, summary
